/* ingage EduTech – courses announced as "Coming soon" (18–22): card pictures and their future S3 folders.
 *   18 Architectural Visualization · 19 Industrial Metaverse · 20 Game Development · 21 Graphic Design · 22 Data Warehousing
 * The course details (description, careers, fee, hours) are in index.html (var C, AIDEF, AISAL) like every other course.
 * Slides and videos will come from Amazon S3 later, in the folders below (same layout as the other courses:
 * <folder>/Slides/<deck>.pptx and <folder>/Videos/<video>.mp4). When they are uploaded, a curriculum file like
 * robot-course.js is added for the course and its "soon" flag is removed in index.html.
 * Loaded before the main script in index.html.
 */
(function (w) {
  'use strict';
  var S3 = 'https://ingage-lms.s3.ap-south-1.amazonaws.com/';
  w.UPCOMING_S3 = {
    18: S3 + 'Architectural+Visualization/',
    19: S3 + 'Industrial+Metaverse/',
    20: S3 + 'Game+Development/',
    21: S3 + 'Graphic+Design/',
    22: S3 + 'Data+Warehousing/',
  };
  // card pictures (800px JPEG, embedded so the single-file build keeps them)
  w.UPC_IMG = {
    18: 'data:image/jpeg;base64,',
    19: 'data:image/jpeg;base64,',
    20: 'data:image/jpeg;base64,',
    21: 'data:image/jpeg;base64,',
    22: 'data:image/jpeg;base64,',
  };
})(window);
